local offLimits = {}

--- Determines if index is in a string
function isOffLimits(index)
    for _, v in pairs(offLimits) do
        if index >= v[1] and index <= v[2] then
            return true
        end
    end
    return false
end

--- Find iterator
-- function gfind(str, pattern)
--     local start = 0
